const PTS_PER_100 = 1, GOLD = 5000, PLAT = 15000, REF_BONUS = 500;
const b = $('Webhook: sale recorded').item.json.body || {};
const phone = String(b.phone||'').replace(/\D/g,'').slice(-10);
if (!phone) return [];
const rows = items.map(i=>i.json);
const tier = p => p >= PLAT ? 'Platinum' : p >= GOLD ? 'Gold' : 'Silver';
const me = rows.find(r => String(r.Phone||'').replace(/\D/g,'').slice(-10) === phone);
const addPts = Math.floor(Number(b.amount||0)/100)*PTS_PER_100;
const oldPts = Number(me?.Points||0), newPts = oldPts + addPts;
const out = [{ json: { kind:'customer', exists: !!me, row_number: me?.row_number, Name: b.name || me?.Name || 'Customer', Phone: phone, Points: newPts, Tier: tier(newPts), TotalSpend: Number(me?.TotalSpend||0)+Number(b.amount||0), upgraded: tier(newPts) !== tier(oldPts) && !!me, addPts } }];
const refPhone = String(b.referred_by||'').replace(/\D/g,'').slice(-10);
if (refPhone) { const ref = rows.find(r => String(r.Phone||'').replace(/\D/g,'').slice(-10) === refPhone);
  if (ref) out.push({ json: { kind:'referrer', exists:true, row_number: ref.row_number, Name: ref.Name, Phone: refPhone, Points: Number(ref.Points||0)+REF_BONUS, Tier: tier(Number(ref.Points||0)+REF_BONUS), TotalSpend: Number(ref.TotalSpend||0), upgraded:false, addPts: REF_BONUS } }); }
return out;
